//! The per-protocol packet table, `protocol.json` (generated by
//! `scripts/gen-presence-protocol.py` from minecraft-data), compiled once
//! for the whole process. Every session shares it.

use std::{io::Cursor, sync::LazyLock};

use serde_json::Value as Json;

use crate::protodef::{self, DecodeError, EncodeError, Type, Value};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum State {
    Login,
    Configuration,
    Play,
}

impl State {
    fn index(self) -> usize {
        self as usize
    }
    pub fn key(self) -> &'static str {
        match self {
            State::Login => "login",
            State::Configuration => "configuration",
            State::Play => "play",
        }
    }
}

struct Entry {
    name: Box<str>,
    id: i32,
    schema: usize,
}

/// The presence packets of one protocol number.
pub struct Dialect {
    pub protocol: i32,
    /// The release names that use this protocol, oldest first.
    pub names: Vec<String>,
    /// [state][0 = to server, 1 = to client]
    packets: [[Vec<Entry>; 2]; 3],
}

struct Table {
    source: String,
    dialects: Vec<Dialect>,
    schemas: Vec<Type>,
}

static TABLE: LazyLock<Table> = LazyLock::new(|| {
    let j: Json = serde_json::from_str(include_str!("../protocol.json")).expect("protocol.json is JSON");
    let schemas = j["schemas"]
        .as_array()
        .expect("schemas")
        .iter()
        .map(|s| Type::compile(s).unwrap_or_else(|e| panic!("protocol.json schema: {e}")))
        .collect();
    let dialects = j["versions"]
        .as_array()
        .expect("versions")
        .iter()
        .map(|v| {
            let mut packets: [[Vec<Entry>; 2]; 3] = Default::default();
            for state in [State::Login, State::Configuration, State::Play] {
                for (dir, key) in ["toServer", "toClient"].iter().enumerate() {
                    if let Some(map) = v["packets"][format!("{}.{key}", state.key())].as_object() {
                        packets[state.index()][dir] = map
                            .iter()
                            .map(|(name, e)| Entry {
                                name: name.as_str().into(),
                                id: e[0].as_i64().expect("packet id") as i32,
                                schema: e[1].as_u64().expect("schema index") as usize,
                            })
                            .collect();
                    }
                }
            }
            Dialect {
                protocol: v["protocol"].as_i64().expect("protocol") as i32,
                names: v["names"].as_array().expect("names").iter().map(|n| n.as_str().unwrap_or("").to_owned()).collect(),
                packets,
            }
        })
        .collect();
    Table { source: j["source"].as_str().unwrap_or("").to_owned(), dialects, schemas }
});

/// The dialect for a protocol number, or `None` when it is not supported.
pub fn dialect(protocol: i32) -> Option<&'static Dialect> {
    TABLE.dialects.iter().find(|d| d.protocol == protocol)
}

/// Every supported dialect, oldest first.
pub fn dialects() -> &'static [Dialect] {
    &TABLE.dialects
}

/// The minecraft-data commit the table came from.
pub fn source() -> &'static str {
    &TABLE.source
}

#[derive(Debug, thiserror::Error)]
pub enum PacketError {
    #[error("{0} has no {1:?} packet {2}")]
    Missing(i32, State, String),
    #[error("encode {0}: {1}")]
    Encode(String, EncodeError),
    #[error("decode {0}: {1}")]
    Decode(String, DecodeError),
}

impl Dialect {
    /// The release name a person would recognize, such as "1.20.4".
    pub fn name(&self) -> &str {
        self.names.last().map_or("", String::as_str)
    }

    /// The protocol has the configuration state (1.20.2 and later).
    pub fn has_configuration(&self) -> bool {
        !self.packets[State::Configuration.index()][1].is_empty()
    }

    /// 1.8 can switch compression on in play, not only in login.
    pub fn has_play_set_compression(&self) -> bool {
        self.packets[State::Play.index()][1].iter().any(|e| &*e.name == "set_compression")
    }

    pub fn has(&self, state: State, name: &str) -> bool {
        self.packets[state.index()][0].iter().any(|e| &*e.name == name)
    }

    /// Every packet of this protocol: state, true for clientbound, name, id,
    /// schema. For tools that check the codec against another implementation.
    pub fn packets(&self) -> impl Iterator<Item = (State, bool, &str, i32, &'static Type)> + '_ {
        [State::Login, State::Configuration, State::Play].into_iter().flat_map(move |state| {
            (0..2).flat_map(move |dir| {
                self.packets[state.index()][dir]
                    .iter()
                    .map(move |e| (state, dir == 1, &*e.name, e.id, &TABLE.schemas[e.schema]))
            })
        })
    }

    /// Encode a serverbound packet: the id, then `fields` in this
    /// protocol's layout.
    pub fn encode(&self, state: State, name: &str, fields: &Value) -> Result<Vec<u8>, PacketError> {
        let e = self.packets[state.index()][0]
            .iter()
            .find(|e| &*e.name == name)
            .ok_or_else(|| PacketError::Missing(self.protocol, state, name.to_owned()))?;
        let mut out = Vec::with_capacity(32);
        protodef::write_varint(&mut out, e.id);
        TABLE.schemas[e.schema].encode(fields, &mut out).map_err(|err| PacketError::Encode(name.to_owned(), err))?;
        Ok(out)
    }

    /// The name of a clientbound packet when it is one the presence client
    /// handles; other packets are never decoded.
    pub fn clientbound_name(&self, state: State, raw: &[u8]) -> Option<&str> {
        let id = protodef::read_varint(&mut Cursor::new(raw)).ok()?;
        self.packets[state.index()][1].iter().find(|e| e.id == id).map(|e| &*e.name)
    }

    /// Decode a clientbound packet of the presence subset.
    pub fn decode(&self, state: State, raw: &[u8]) -> Result<Option<(&str, Value)>, PacketError> {
        let mut cur = Cursor::new(raw);
        let Ok(id) = protodef::read_varint(&mut cur) else {
            return Ok(None);
        };
        let Some(e) = self.packets[state.index()][1].iter().find(|e| e.id == id) else {
            return Ok(None);
        };
        let v = TABLE.schemas[e.schema].decode(&mut cur).map_err(|err| PacketError::Decode(e.name.to_string(), err))?;
        Ok(Some((&*e.name, v)))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_schema_compiles_and_the_range_is_contiguous() {
        let d = dialects();
        assert_eq!(d.first().map(|d| d.protocol), Some(4));
        assert_eq!(d.last().map(|d| d.name()), Some("26.3"));
        assert!(d.windows(2).all(|w| w[0].protocol < w[1].protocol));
        assert!(!source().is_empty());
    }

    #[test]
    fn every_dialect_has_the_packets_a_session_needs() {
        for d in dialects() {
            for name in ["login_start", "encryption_begin"] {
                assert!(d.has(State::Login, name), "{} lacks login {name}", d.name());
            }
            for name in ["keep_alive", "settings", "client_command", "look"] {
                assert!(d.has(State::Play, name), "{} lacks play {name}", d.name());
            }
            assert!(d.has(State::Play, "arm_animation") || d.has(State::Play, "punch"), "{} cannot swing", d.name());
            assert!(d.has(State::Play, "entity_action") || d.has(State::Play, "player_input"), "{} cannot sneak", d.name());
            assert!(d.has(State::Play, "chat") || d.has(State::Play, "chat_message"), "{} has no chat", d.name());
            assert!(d.has(State::Play, "teleport_confirm") || d.has(State::Play, "position_look"), "{}", d.name());
            assert_eq!(d.has_configuration(), d.has(State::Login, "login_acknowledged"), "{}", d.name());
        }
    }

    #[test]
    fn every_serverbound_packet_encodes_from_no_fields_and_decodes_back() {
        // Encoding fills left-out fields with zeros; decoding the bytes with
        // the same schema must consume them exactly.
        for d in dialects() {
            for state in [State::Login, State::Configuration, State::Play] {
                for e in &d.packets[state.index()][0] {
                    let bytes = d.encode(state, &e.name, &Value::Map(vec![])).unwrap();
                    let mut cur = Cursor::new(&bytes[..]);
                    assert_eq!(protodef::read_varint(&mut cur).unwrap(), e.id);
                    TABLE.schemas[e.schema].decode(&mut cur).unwrap();
                    assert_eq!(cur.position() as usize, bytes.len(), "{} {:?} {}", d.name(), state, e.name);
                }
            }
        }
    }

    #[test]
    fn no_input_makes_any_schema_panic() {
        // Random bytes, and every prefix of a valid encoding, against every
        // schema: decoding returns a value or an error, never panics.
        let mut x: u64 = 0x2545_f491_4f6c_dd1d;
        let mut next = move || {
            x ^= x << 13;
            x ^= x >> 7;
            x ^= x << 17;
            x
        };
        for (i, schema) in TABLE.schemas.iter().enumerate() {
            for round in 0..20_000 {
                let len = (next() % 96) as usize;
                let mut bytes: Vec<u8> = (0..len).map(|_| next() as u8).collect();
                if round % 4 == 0 && !bytes.is_empty() {
                    // huge varint counts and lengths
                    bytes[0] = 0xff;
                    bytes.splice(1..1, [0xff, 0xff, 0xff, 0x07]);
                }
                let _ = schema.decode(&mut Cursor::new(&bytes[..]));
            }
            let mut full = Vec::new();
            let empty = if matches!(schema, Type::Container(_)) { Value::Map(vec![]) } else { Value::None };
            schema.encode(&empty, &mut full).unwrap();
            for cut in 0..full.len() {
                let _ = schema.decode(&mut Cursor::new(&full[..cut]));
            }
            let _ = i;
        }
    }

    #[test]
    fn a_forged_count_of_empty_items_is_refused() {
        let t = Type::Array(protodef::Len::VarInt, Box::new(Type::Void));
        let mut bytes = Vec::new();
        protodef::write_varint(&mut bytes, i32::MAX);
        assert!(t.decode(&mut Cursor::new(&bytes[..])).is_err());
    }

    #[test]
    fn keep_alive_width_follows_the_protocol() {
        let one_eight = dialect(47).unwrap();
        let modern = dialect(775).unwrap();
        let v = crate::fields! { "keepAliveId" => 300i64 };
        assert_eq!(one_eight.encode(State::Play, "keep_alive", &v).unwrap().len(), 1 + 2);
        assert_eq!(modern.encode(State::Play, "keep_alive", &v).unwrap().len(), 1 + 8);
    }
}
